import {useState} from 'react';
import {Pressable,StyleSheet,Text,View} from '@/platform/react-native';
import {router,useLocalSearchParams} from '@/router';
import {useQuery} from '@tanstack/react-query';
import {Ionicons} from '@/platform/icons';
import {api} from '@/lib/api';
import {Card,EmptyState,Input,Muted,Screen,useAppTheme} from '@/components/UI';
export default function AttendanceHistory(){
 const{id}=useLocalSearchParams<{id:string}>();const{palette}=useAppTheme();const[search,setSearch]=useState('');
 const q=useQuery<any>({queryKey:['attendance',id],queryFn:async()=>(await api.get(`/communities/${id}/attendance`)).data});
 const meetings=(q.data?.meetings||[]).filter((m:any)=>new Date(m.EndDateTime)<new Date()&&m.Title.toLowerCase().includes(search.toLowerCase()));
 const totals=meetings.reduce((a:any,m:any)=>({members:a.members+Number(m.MemberCount||0),present:a.present+Number(m.PresentCount||0)}),{members:0,present:0});
 return <Screen scroll contentStyle={s.page}><Card style={s.stats}><Stat icon="calendar-outline" label="Meetings" value={meetings.length} color={palette.primary}/><Stat icon="people-outline" label="Members" value={totals.members} color={palette.info}/><Stat icon="checkmark-circle-outline" label="Present" value={totals.present} color={palette.success}/></Card><Input placeholder="Search by meeting title" value={search} onChangeText={setSearch}/>{q.isError?<Card style={s.error}><Ionicons name="alert-circle-outline" size={30} color={palette.danger}/><Text style={[s.errorTitle,{color:palette.text}]}>Unable to load attendance history</Text><Muted>Check your connection and try again.</Muted><Pressable accessibilityRole="button" onPress={()=>q.refetch()} style={[s.retry,{backgroundColor:palette.primary}]}><Text style={s.retryText}>Try again</Text></Pressable></Card>:meetings.length?meetings.map((m:any)=>{const pct=m.MemberCount?Math.round(m.PresentCount/m.MemberCount*100):0;return <Pressable key={m.Id} onPress={()=>router.push(`/community/${id}/attendance/${m.Id}` as any)}><Card style={s.row}><View style={[s.icon,{backgroundColor:palette.primarySoft}]}><Ionicons name="people-outline" size={25} color={palette.primary}/></View><View style={{flex:1}}><Text style={[s.meeting,{color:palette.text}]}>{m.Title}</Text><Muted>{new Date(m.StartDateTime).toLocaleString()}</Muted><Muted>{m.PresentCount||0} present · {m.LateCount||0} late</Muted></View><View style={[s.percent,{borderColor:palette.success}]}><Text style={{color:palette.success,fontWeight:'900'}}>{pct}%</Text></View><Ionicons name="chevron-forward" size={20} color={palette.muted}/></Card></Pressable>}):q.isLoading?<Muted>Loading attendance history…</Muted>:<EmptyState icon="time-outline" title="No attendance history" body="Completed meetings will appear here with their recorded participants."/>}</Screen>
}
function Stat({icon,label,value,color}:{icon:any;label:string;value:number;color:string}){return <View style={s.stat}><Ionicons name={icon} size={25} color={color}/><Text style={[s.statValue,{color}]}>{value}</Text><Muted>{label}</Muted></View>}
const s=StyleSheet.create({page:{width:'100%',maxWidth:850,alignSelf:'center',paddingBottom:120},stats:{flexDirection:'row',paddingVertical:22},stat:{flex:1,alignItems:'center',gap:3},statValue:{fontSize:24,fontWeight:'900'},row:{flexDirection:'row',alignItems:'center',gap:12},icon:{width:54,height:54,borderRadius:18,alignItems:'center',justifyContent:'center'},meeting:{fontSize:16,fontWeight:'900'},percent:{width:54,height:54,borderRadius:27,borderWidth:5,alignItems:'center',justifyContent:'center'},error:{alignItems:'center',gap:8,paddingVertical:28},errorTitle:{fontSize:17,fontWeight:'900',textAlign:'center'},retry:{minWidth:130,minHeight:44,borderRadius:12,alignItems:'center',justifyContent:'center',marginTop:6},retryText:{color:'#FFFFFF',fontWeight:'900'}})
